import math

def implied_move(S, sigma, T):
    return S * sigma * math.sqrt(T)

def atm_straddle_approx(S, sigma, T):
    return 0.7979 * S * sigma * math.sqrt(T)

S, T = 26500, 7 / 365
pre_event_iv, post_event_iv = 0.198, 0.135

move = implied_move(S, pre_event_iv, T)
pre = atm_straddle_approx(S, pre_event_iv, T)
post = atm_straddle_approx(S, post_event_iv, T)

print(f"Implied 1-sigma move: {move:.0f}")
print(f"Straddle pre-event: {pre:.0f}, post-event: {post:.0f}, crush: {(pre - post) / pre:.1%}")
